<template>
  <div class="container contact-page"><header><span class="eyebrow">CBJJ SUPPORT</span><h1>{{ isZh ? '联系我们' : 'Contact us' }}</h1><p>{{ isZh ? '订单、商品、退换货、保修及合作咨询，请通过以下真实联系方式联系我们。' : 'Contact us for orders, product questions, returns, warranty and partnership inquiries.' }}</p></header><div class="contact-grid"><section class="contact-details"><h2>CBJJ</h2><p>{{ brand.operator }}</p><dl><dt>{{ isZh ? '客服邮箱' : 'Customer support email' }}</dt><dd><a :href="`mailto:${brand.email}`">{{ brand.email }}</a></dd><dt>{{ isZh ? '客服电话' : 'Customer support phone' }}</dt><dd><a :href="`tel:${brand.phoneHref}`">{{ brand.phone }}</a></dd><dt>{{ isZh ? '公司联系地址' : 'Company contact address' }}</dt><dd>{{ isZh ? brand.addressZh : brand.addressEn }}</dd><dt>{{ isZh ? '公司秘书联系电话' : 'Company secretarial contact' }}</dt><dd><a href="tel:+85266576931">{{ brand.secretaryPhone }}</a><small>{{ isZh ? '公司秘书服务，非商品售后热线。' : 'Company secretarial service; use customer support for product inquiries.' }}</small></dd></dl><p class="note">{{ isZh ? '该地址不是退货仓库，请先联系客服取得退货指引。' : 'This office is not a returns warehouse. Contact support for return instructions.' }}</p></section><form @submit.prevent="openEmail"><h2>{{ isZh ? '准备一封客服邮件' : 'Prepare a support email' }}</h2><p>{{ isZh ? '此表单会打开您的邮件应用并预填内容，邮件需要您自行发送；不会在网页中直接提交。' : 'This form opens your email application with a prepared message. You must send the email yourself; the form does not submit a message online.' }}</p><label>{{ isZh ? '姓名' : 'Name' }}<input v-model="form.name" required maxlength="100" autocomplete="name" /></label><label>{{ isZh ? '邮箱' : 'Email' }}<input v-model="form.email" required type="email" maxlength="254" autocomplete="email" /></label><label>{{ isZh ? '订单号（选填）' : 'Order number (optional)' }}<input v-model="form.order" maxlength="100" /></label><label>{{ isZh ? '问题说明' : 'Message' }}<textarea v-model="form.message" required rows="5" maxlength="5000" /></label><button type="submit">{{ isZh ? '打开邮件应用' : 'Open email application' }} →</button><p v-if="opened" role="status">{{ isZh ? '请在邮件应用中发送。如果应用未打开，可直接写信至下方邮箱。' : 'Send the message in your email application. If it did not open, email us directly using the address below.' }}</p><a :href="`mailto:${brand.email}`">{{ brand.email }}</a><NuxtLink to="/pages/privacy-policy">{{ isZh ? '查看隐私政策' : 'Read our privacy policy' }}</NuxtLink></form></div></div>
</template>
<script setup lang="ts">
import { reactive, ref } from 'vue'
import { brand } from '~/data/brand'
const { isZh } = useShopLocale()
const form = reactive({ name: '', email: '', order: '', message: '' })
const opened = ref(false)
const openEmail = () => {
  const subject = `CBJJ support${form.order ? ` · ${form.order}` : ''}`
  const body = `Name: ${form.name}\nEmail: ${form.email}\nOrder: ${form.order}\n\n${form.message}`
  window.location.href = `mailto:${brand.email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`
  opened.value = true
}
useSeoMeta({ title: () => isZh.value ? '联系我们 | CBJJ' : 'Contact us | CBJJ', description: () => isZh.value ? 'CBJJ 客服及公司联系信息。' : 'CBJJ customer support and company contact information.' })
</script>
